// Edit these three values after import.
const SETTINGS = {
  CLIENTS_CSV_URL: "https://docs.google.com/spreadsheets/d/e/XXXX/pub?output=csv",
  VAPI_ASSISTANT_ID: "your-speed-to-lead-assistant-id",
  VAPI_PHONE_NUMBER_ID: "your-imported-twilio-number-id",
};

const lead = $('Lead form webhook').first().json.body || {};
const csv = $input.first().json.data || "";

// Tiny CSV parser (quoted fields supported)
function parseCsv(text) {
  const rows = []; let row = [], f = "", q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"' && text[i+1] === '"') { f += '"'; i++; } else if (c === '"') q = false; else f += c; }
    else if (c === '"') q = true;
    else if (c === ',') { row.push(f); f = ""; }
    else if (c === '\n' || c === '\r') { if (c === '\r' && text[i+1] === '\n') i++; row.push(f); rows.push(row); row = []; f = ""; }
    else f += c;
  }
  if (f || row.length) { row.push(f); rows.push(row); }
  const [h, ...b] = rows.filter(r => r.some(x => x.trim()));
  return b.map(r => Object.fromEntries(h.map((k, i) => [k.trim(), (r[i] || "").trim()])));
}

const client = parseCsv(csv).find(r => r.client_id === lead.client_id);
if (!client) throw new Error(`Unknown client_id: ${lead.client_id}`);

const d = String(lead.phone || "").replace(/\D/g, "");
const number = String(lead.phone || "").trim().startsWith("+") ? `+${d}` : (d.length === 10 ? `+1${d}` : `+${d}`);
const name = String(lead.name || "").trim();

return [{ json: {
  client_id: client.client_id,
  business_name: client.business_name,
  vapiPayload: {
    assistantId: SETTINGS.VAPI_ASSISTANT_ID,
    phoneNumberId: SETTINGS.VAPI_PHONE_NUMBER_ID,
    customer: { number, name },
    assistantOverrides: { variableValues: {
      agent_name: client.agent_name,
      business_name: client.business_name,
      offer: lead.offer || client.offer,
      lead_first_name: name.split(/\s+/)[0],
      lead_message: lead.message || "no message",
      q1: client.q1, q2: client.q2, q3: client.q3,
      meeting_type: client.meeting_type,
      price_guidance: client.price_guidance,
    } },
  },
} }];
